', direction=None, fact=None, file_name='/workspace/sandbox/variants/accessible_minimal/modal-dialog--framework-vanilla-js--style-modern/claude-sonnet-4.6__s4/script.js', full_command_text=None, has_write_file_redirection=None, hook_message=None, intention='Create file', new_file_contents='(function () {
  const overlay = document.getElementById('deleteModal');
  const trigger = document.getElementById('deleteBtn');
  const cancelBtn = document.getElementById('cancelDelete');
  const confirmBtn = document.getElementById('confirmDelete');
  const closeBtn = document.getElementById('modalClose');

  function openModal() {
    overlay.classList.add('is-open');
    overlay.removeAttribute('aria-hidden');
    // Move focus into the dialog
    cancelBtn.focus();
  }

  function closeModal() {
    overlay.classList.remove('is-open');
    overlay.setAttribute('aria-hidden', 'true');
    trigger.focus();
  }

  trigger.addEventListener('click', openModal);
  cancelBtn.addEventListener('click', closeModal);
  closeBtn.addEventListener('click', closeModal);

  confirmBtn.addEventListener('click', function () {
    closeModal();
    // Replace card with a success notice
    const card = document.getElementById('imageCard');
    card.innerHTML = `
      <div style="padding:48px 24px;text-align:center;color:var(--text-secondary);">
        <svg xmlns="http://www.w3.org/2000/svg" width="48" height="48" fill="none" viewBox="0 0 24 24" aria-hidden="true">
          <circle cx="12" cy="12" r="10" stroke="#e53e3e" stroke-width="1.5"/>
          <path stroke="#e53e3e" stroke-width="1.5" stroke-linecap="round" d="M9 12l2 2 4-4"/>
        </svg>
        <p style="margin-top:16px;font-size:1rem;font-weight:600;color:var(--text-primary);">Image deleted</p>
        <p style="margin-top:4px;font-size:0.875rem;">The image has been removed from your library.</p>
      </div>`;
  });

  // Close on backdrop click
  overlay.addEventListener('click', function (e) {
    if (e.target === overlay) closeModal();
  });

  // Close on Escape
  document.addEventListener('keydown', function (e) {
    if (e.key === 'Escape' && overlay.classList.contains('is-open')) {
      closeModal();
    }
  });

  // Trap focus inside the modal while open
  overlay.addEventListener('keydown', function (e) {
    if (e.key !== 'Tab' || !overlay.classList.contains('is-open')) return;
    const focusable = overlay.querySelectorAll(
      'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])'
    );
    const first = focusable[0];
    const last = focusable[focusable.length - 1];
    if (e.shiftKey) {
      if (document.activeElement === first) { e.preventDefault(); last.focus(); }
    } else {
      if (document.activeElement === last) { e.preventDefault(); first.focus(); }
    }
  });
})();
